
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_mn12_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_mn12_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.000559939032865e-01, -2.892895577475970e-01, -2.752767917528003e-01, -2.577472260738382e-01, -2.366521206999308e-01, -2.109672315976160e-01, -1.741081455447517e-01, -1.084509801776257e-01, -9.959846717290118e-03, 8.180266535700190e-02, 1.324332878056896e-01, -6.796341483854108e-02, -4.596975940725673e-02, -3.540829355719667e-02, 8.762846045712678e-03, 6.786199096558700e-02, -2.608236290057043e-02, -5.106706120178003e-02, -1.618765935220149e-02, -2.319282770414303e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


